export class AgentClient {
  public readonly transport: HpdTransport;
  public readonly agentEvents: AgentEventsService;
  public readonly agentInputs: AgentInputsService;
  public readonly agentInteractions: AgentInteractionsService;
  public readonly agentRuntime: AgentRuntimeService;
  public readonly agents: AgentsService;
  public readonly clientTools: ClientToolsService;
  public readonly content: ContentService;
  public readonly evaluations: EvaluationsService;
  public readonly executions: ExecutionsService;
  public readonly runtimeExtensions: RuntimeExtensionsService;
  public readonly sessions: SessionsService;
  public readonly threads: ThreadsService;

  public constructor(baseUrl: string, options: ClientOptions = {}) {
    this.transport = new HpdTransport(baseUrl, options);
    this.agentEvents = new AgentEventsService(this.transport);
    this.agentInputs = new AgentInputsService(this.transport);
    this.agentInteractions = new AgentInteractionsService(this.transport);
    this.agentRuntime = new AgentRuntimeService(this.transport);
    this.agents = new AgentsService(this.transport);
    this.clientTools = new ClientToolsService(this.transport);
    this.content = new ContentService(this.transport);
    this.evaluations = new EvaluationsService(this.transport);
    this.executions = new ExecutionsService(this.transport);
    this.runtimeExtensions = new RuntimeExtensionsService(this.transport);
    this.sessions = new SessionsService(this.transport);
    this.threads = new ThreadsService(this.transport);
  }
}
